#include <exiv2/exiv2.hpp>
#include <iostream>

using namespace Exiv2;

static void dump(const XmpData& d, const std::string& label) {
  std::cout << "== " << label << " (" << d.count() << " entries)\n";
  for (const auto& m : d) {
    std::cout << "  " << m.key() << " = " << m.value() << "\n";
  }
}

int main() {
  // Scenario 1: packet with a custom (internal) namespace, round-trip it
  const std::string packet =
      R"(<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>)"
      R"(<x:xmpmeta xmlns:x="adobe:ns:meta/">)"
      R"(<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">)"
      R"(<rdf:Description rdf:about="")"
      R"( xmlns:acme="https://acme.example.com/xmp/1.0/")"
      R"( acme:ProjectId="PRJ-42")"
      R"( acme:Confidence="0.95"/>)"
      R"(</rdf:RDF></x:xmpmeta><?xpacket end="w"?>)";

  XmpData xmp;
  int rc = XmpParser::decode(xmp, packet);
  std::cout << "decode rc=" << rc << "\n";
  dump(xmp, "decoded custom ns");

  std::string out;
  rc = XmpParser::encode(out, xmp);
  std::cout << "encode rc=" << rc << "\n";
  std::cout << out << "\n";

  // Scenario 2: mutate an existing custom property and write back
  xmp["Xmp.acme.ProjectId"] = "PRJ-43";
  out.clear();
  rc = XmpParser::encode(out, xmp);
  std::cout << "mutate encode rc=" << rc << "\n";
  std::cout << out << "\n";

  // Scenario 3: copy XmpData (e.g. image read -> image write through copy)
  {
    XmpData copy = xmp;
    std::string out2;
    rc = XmpParser::encode(out2, copy);
    std::cout << "copy encode rc=" << rc << "\n";
    std::cout << out2 << "\n";
  }

  // Scenario 4: brand-new XmpData with a custom key without explicit registerNs
  {
    XmpData fresh;
    try {
      fresh["Xmp.acme.FreshProp"] = "hello";
      std::string out3;
      rc = XmpParser::encode(out3, fresh);
      std::cout << "fresh encode rc=" << rc << "\n";
      std::cout << out3 << "\n";
    } catch (const Exiv2::Error& e) {
      std::cout << "fresh FAILED: " << e << "\n";
    }
  }

  // Scenario 5: two different packets bind the SAME prefix to different URIs
  {
    const std::string packetB =
        R"(<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>)"
        R"(<x:xmpmeta xmlns:x="adobe:ns:meta/">)"
        R"(<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">)"
        R"(<rdf:Description rdf:about="")"
        R"( xmlns:acme="https://acme-other.example.com/xmp/2.0/")"
        R"( acme:OtherThing="zzz"/>)"
        R"(</rdf:RDF></x:xmpmeta><?xpacket end="w"?>)";
    XmpData b;
    XmpParser::decode(b, packetB);
    dump(b, "other URI same prefix");
    std::string out4;
    XmpParser::encode(out4, b);
    std::cout << out4 << "\n";
  }

  // Re-encode original to check for cross-instance leakage
  {
    std::string out5;
    XmpParser::encode(out5, xmp);
    std::cout << "original after other decode:\n" << out5 << "\n";
  }
}

