#include <exiv2/exiv2.hpp>
#include <cassert>
#include <iostream>

using namespace Exiv2;

static DecodeParams dp(100);

static std::string wrap(const std::string& prefix, const std::string& uri, const std::string& tag,
                        const std::string& value) {
  return std::string(R"(<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>)"
                     R"(<x:xmpmeta xmlns:x="adobe:ns:meta/">)"
                     R"(<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">)"
                     R"(<rdf:Description rdf:about="")"
                     R"( xmlns:)") +
         prefix + R"("=")" + uri + R"(" )" + prefix + ":" + tag + R"(=")" + value +
         R"("/></rdf:RDF></x:xmpmeta><?xpacket end="w"?>)";
}

int main() {
  // A: full round trip, then decode the ENCODED packet again and compare values
  {
    const std::string p = wrap("acme", "https://acme.example.com/xmp/1.0/", "ProjectId", "PRJ-42");
    XmpData d;
    assert(XmpParser::decode(d, p, dp) == 0);
    std::string out;
    assert(XmpParser::encode(out, d, XmpParser::omitPacketWrapper) == 0);
    XmpData d2;
    assert(XmpParser::decode(d2, out, dp) == 0);
    assert(d2.count() == 1);
    std::cout << "A re-decode: " << d2.begin()->key() << " = " << d2.begin()->value() << "\n";
  }

  // B: decode custom packet, then ADD a property in another custom ns that is
  //    globally registered programmatically (like an app doing registerNs first)
  {
    XmpProperties::registerNs("https://vendor.example/ns/2.0/", "vendor");
    const std::string p = wrap("acme", "https://acme.example.com/xmp/1.0/", "ProjectId", "PRJ-42");
    XmpData d;
    assert(XmpParser::decode(d, p, dp) == 0);
    d["Xmp.vendor.Region"] = "eu-west";
    std::string out;
    assert(XmpParser::encode(out, d, XmpParser::omitPacketWrapper) == 0);
    const bool hasAcme = out.find("https://acme.example.com/xmp/1.0/") != std::string::npos;
    const bool hasVendor = out.find("https://vendor.example/ns/2.0/") != std::string::npos;
    std::cout << "B hasAcme=" << hasAcme << " hasVendor=" << hasVendor << "\n";
    assert(hasAcme && hasVendor);
  }

  // C: same prefix, two URIs, then MERGE properties from both into a fresh object
  //    (simulates copying metadata between images)
  {
    XmpData a, b;
    assert(XmpParser::decode(a, wrap("shared", "http://example.com/A/1.0/", "TagA", "1"), dp) == 0);
    assert(XmpParser::decode(b, wrap("shared", "http://example.com/B/1.0/", "TagB", "2"), dp) == 0);
    XmpData merged = a;
    for (const auto& m : b)
      merged.add(*m.key().clone(), &m.value());
    std::string out;
    int rc = XmpParser::encode(out, merged, XmpParser::omitPacketWrapper);
    std::cout << "C merge encode rc=" << rc << "\n" << out << "\n";
  }

  // D: erase the only custom property, then re-add; bindings must stay coherent
  {
    const std::string p = wrap("acme", "https://acme.example.com/xmp/1.0/", "ProjectId", "PRJ-42");
    XmpData d;
    assert(XmpParser::decode(d, p, dp) == 0);
    d.erase(d.findKey(XmpKey("Xmp.acme.ProjectId")));
    d["Xmp.acme.ProjectId"] = "PRJ-99";
    std::string out;
    int rc = XmpParser::encode(out, d, XmpParser::omitPacketWrapper);
    std::cout << "D erase/readd rc=" << rc << " hasURI="
              << (out.find("https://acme.example.com/xmp/1.0/") != std::string::npos) << "\n";
  }

  // E: packet whose custom prefix collides with a STANDARD prefix (rebinding dc)
  {
    const std::string evil =
        std::string(R"(<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>)"
                    R"(<x:xmpmeta xmlns:x="adobe:ns:meta/">)"
                    R"(<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">)"
