                    R"(</rdf:RDF></x:xmpmeta><?xpacket end="w"?>)");
    XmpData d;
    int rc = XmpParser::decode(d, evil, dp);
    std::cout << "E decode rc=" << rc << " count=" << d.count() << "\n";
    for (const auto& m : d)
      std::cout << "  " << m.key() << " = " << m.value() << "\n";
    std::string out;
    rc = XmpParser::encode(out, d, XmpParser::omitPacketWrapper);
    std::cout << "E encode rc=" << rc << "\n" << out << "\n";
  }
}

