#include <exiv2/exiv2.hpp>
#include <cassert>
#include <iostream>

using namespace Exiv2;

int main() {
  // High-level Image API on an in-memory JPEG with a custom XMP namespace
  const std::string packet =
      R"(<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>)"
      R"(<x:xmpmeta xmlns:x="adobe:ns:meta/">)"
      R"(<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">)"
      R"(<rdf:Description rdf:about="")"
      R"( xmlns:acme="https://acme.example.com/xmp/1.0/")"
      R"( acme:ProjectId="PRJ-42"/>)"
      R"(</rdf:RDF></x:xmpmeta><?xpacket end="w"?>)";

  // XMP sidecar via the high-level Image factory
  {
    auto img = ImageFactory::open(ImageType::xmp, std::vector<byte>{});
    img->setXmpPacket(packet);
    img->writeMetadata();
    const auto& out = img->xmpPacket();
    std::cout << "sidecar write contains custom URI: "
              << (out.find("https://acme.example.com/xmp/1.0/") != std::string::npos) << "\n";

    // Re-open the produced sidecar and read back
    auto img2 = ImageFactory::open(ImageType::xmp,
                                   std::vector<byte>(out.begin(), out.end()));
    img2->readMetadata();
    const auto& d2 = img2->xmpData();
    std::cout << "sidecar re-read count=" << d2.count() << "\n";
    for (const auto& m : d2)
      std::cout << "  " << m.key() << " = " << m.value() << "\n";
  }

  // JPEG round trip through a real file
  {
    auto img = ImageFactory::open("repro4_in.jpg");
    img->readMetadata();
    img->xmpData()["Xmp.acme.ProjectId"] = "PRJ-77";
    img->writeMetadata();

    auto img2 = ImageFactory::open("repro4_in.jpg");
    img2->readMetadata();
    const auto& d = img2->xmpData();
    bool found = false;
    for (const auto& m : d) {
      std::cout << "jpeg " << m.key() << " = " << m.value() << "\n";
      if (m.key() == "Xmp.acme.ProjectId")
        found = m.value().toString() == "PRJ-77";
    }
    std::cout << "jpeg custom property persisted: " << found << "\n";
    assert(found);
  }
}

