#include <exiv2/exiv2.hpp>
#include <iostream>

using namespace Exiv2;

static DecodeParams dp(100);

int main() {
  const std::string uri = "https://clear-test.example.com/ns/1.0/";
  XmpProperties::registerNs(uri, "clrtest");

  // Toolkit knows the prefix after registerNs (encode triggers toolkit sync)
  {
    XmpData d;
    d["Xmp.clrtest.Foo"] = "bar";
    std::string out;
    XmpParser::encode(out, d);
    std::cout << "before clear, packet has URI: " << (out.find(uri) != std::string::npos) << "\n";
  }

  XmpParser::clearCustomNamespaces();

  // Exiv2 registry no longer knows it
  std::cout << "exiv2 ns() after clear: '" << XmpProperties::ns("clrtest") << "'\n";

  // Re-register the SAME prefix with a DIFFERENT URI (common reuse pattern)
  const std::string uri2 = "https://clear-test.example.com/ns/2.0/";
  XmpProperties::registerNs(uri2, "clrtest");
  {
    XmpData d;
    d["Xmp.clrtest.Foo"] = "bar";
    std::string out;
    int rc = XmpParser::encode(out, d);
    std::cout << "re-register encode rc=" << rc << "\n";
    std::cout << "  has old URI: " << (out.find(uri) != std::string::npos) << "\n";
    std::cout << "  has new URI: " << (out.find(uri2) != std::string::npos) << "\n";
  }

  // What does the toolkit itself report now?
  Dictionary dict;
  XmpParser::registeredNamespaces(dict);
  for (const auto& [u, p] : dict) {
    if (u.find("clear-test") != std::string::npos)
      std::cout << "toolkit registry: " << p << " -> " << u << "\n";
  }
}

