  }

  std::cerr << "step3 clear\n";
  XmpParser::clearCustomNamespaces();

  // Exiv2 registry no longer knows it
  std::cerr << "step4 ns query\n";
  try {
    std::cout << "exiv2 ns() after clear: '" << XmpProperties::ns("clrtest") << "'\n";
  } catch (const Exiv2::Error& e) {
    std::cout << "exiv2 ns() after clear throws: " << e.what() << "\n";
  }

  // What does the toolkit itself report right after clear?
  std::cerr << "step5 toolkit dump\n";
  Dictionary dict;
  XmpProperties::registeredNamespaces(dict);
  for (const auto& [u, p] : dict) {
