      std::cout << "re-register encode rc=" << rc << "\n";
      std::cout << "  has old URI: " << (out.find(uri) != std::string::npos) << "\n";
      std::cout << "  has new URI: " << (out.find(uri2) != std::string::npos) << "\n";
    } catch (const std::exception& e) {
      std::cout << "re-register encode THREW: " << e.what() << "\n";
    }
